Confirmed the API: `App#default` is the decorator cyclopts provides for registering the no-subcommand fallback handler.

```python
from cyclopts import App

app = App(name="myservice", help="Manage the myservice daemon.")


@app.default
def status():
    """Show the current status of the service.

    This runs automatically when the program is invoked with no subcommand.
    """
    print("Service status: running")


@app.command
def start():
    """Start the service."""
    print("Service started.")


@app.command
def stop():
    """Stop the service."""
    print("Service stopped.")


if __name__ == "__main__":
    app()
